let controller;

export async function search(term, onResult, onError) {
  // Cancel whatever the previous keystroke started. Without this, response
  // order decides what the user sees, and the network does not guarantee it.
  controller?.abort();
  controller = new AbortController();
  const { signal } = controller;

  // Composes: the same signal aborts the fetch and clears the timeout.
  const timeout = AbortSignal.timeout(8000);
  const combined = AbortSignal.any([signal, timeout]);

  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(term)}`, {
      signal: combined,
    });
    if (!res.ok) throw new Error(`Search failed: ${res.status}`);
    onResult(await res.json());
  } catch (err) {
    // An abort is the expected path, not a failure to report. Showing it as
    // an error is why some search boxes flash "something went wrong" while
    // the user is still typing.
    if (err.name === 'AbortError') return;
    onError(err);
  }
}

// Independent work runs together, and one failure does not discard the rest.
export async function loadFacets(ids) {
  const results = await Promise.allSettled(ids.map((id) => fetchFacet(id)));
  return results
    .filter((r) => r.status === 'fulfilled')
    .map((r) => r.value);
}
